"""Self-contained management console assets for the local coordinator."""

from __future__ import annotations

import html


ASSET_VERSION = "v3"


def console_html(identity: str, roles: list[str]) -> str:
    return f"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>BlobForge Administration</title><link rel="stylesheet" href="/static/management-{ASSET_VERSION}.css"></head>
<body><div class="shell"><aside><a class="brand" href="/"><span class="brand-mark">B</span><span>BlobForge</span></a>
<nav aria-label="Management sections">
<button class="nav active" data-view="dashboard">Overview</button><button class="nav" data-view="jobs">Jobs</button>
<button class="nav" data-view="workers">Workers</button><button class="nav" data-view="recipes">Recipes</button>
<button class="nav" data-view="quotas">Quotas</button><button class="nav" data-view="access">Access</button></nav>
<div class="aside-foot"><a href="/docs">API documentation ↗</a><form method="post" action="/auth/logout" id="logout-form"><button>Sign out</button></form></div></aside>
<main><header><div><p class="eyebrow" id="view-kicker">Administration</p><h1 id="view-title">Overview</h1></div>
<div class="identity"><span>{html.escape(identity)}</span><small>{html.escape(', '.join(roles))}</small></div></header>

<section class="view active" id="view-dashboard"><div class="cards" id="overview-cards"></div>
<div class="grid two"><article class="panel"><div class="panel-head"><div><h2>Queue</h2><p>Current work by priority.</p></div><button class="quiet" data-go="jobs">Open jobs</button></div><div id="priority-chart" class="bars"></div></article>
<article class="panel"><div class="panel-head"><div><h2>Workers</h2><p>Recently registered conversion capacity.</p></div><button class="quiet" data-go="workers">Manage</button></div><div id="worker-summary"></div></article></div>
<article class="panel"><div class="panel-head"><div><h2>Recent activity</h2><p>Administrative mutations are recorded here.</p></div><button class="quiet" id="refresh-overview">Refresh</button></div><div id="audit-list" class="activity"></div></article></section>

<section class="view" id="view-jobs"><div class="toolbar"><input id="job-search" type="search" placeholder="Search names, hashes, paths, or tags">
<select id="job-status"><option value="">All states</option><option>todo</option><option>processing</option><option>failed</option><option>dead</option><option>done</option></select>
<select id="job-priority"><option value="">All priorities</option><option>1_urgent</option><option>2_high</option><option>3_normal</option><option>4_low</option></select>
<button class="primary" id="open-upload">Add source</button></div>
<div class="panel table-wrap"><table><thead><tr><th>Source</th><th>State</th><th>Priority</th><th>Recipe</th><th>Updated</th><th></th></tr></thead><tbody id="jobs-body"></tbody></table>
<div class="pagination"><span id="jobs-total"></span><div><button class="quiet" id="jobs-prev">Previous</button><button class="quiet" id="jobs-next">Next</button></div></div></div></section>

<section class="view" id="view-workers"><div class="section-actions"><p>Worker credentials are shown once. A worker may advertise multiple media and recipe capabilities.</p><button class="primary" id="open-worker">Register worker</button></div>
<div class="panel table-wrap"><table><thead><tr><th>Worker</th><th>Status</th><th>Host</th><th>Last seen</th><th>Ownership</th><th></th></tr></thead><tbody id="workers-body"></tbody></table></div></section>

<section class="view" id="view-recipes"><div class="section-actions"><p>Recipes are immutable conversion identities advertised by workers. Administrators can label or retire them, but cannot rewrite their digest-defining content.</p><button class="primary" id="open-reprocess">Plan upgrades</button></div>
<div class="panel table-wrap"><table><thead><tr><th>Recipe</th><th>Backend</th><th>Media</th><th>Workers</th><th>Status</th><th></th></tr></thead><tbody id="recipes-body"></tbody></table></div></section>

<section class="view" id="view-quotas"><div class="section-actions"><p>Hosted-provider budgets reserve allowance before a cache miss. Provider credentials are never stored here.</p><div><button class="quiet" id="open-provider-account">Configure account</button> <button class="primary" id="open-quota-policy">Add policy window</button></div></div>
<div class="cards" id="quota-cards"></div><article class="panel"><div class="panel-head"><div><h2>Provider accounts</h2><p>Cooldown and concurrency are shared by every worker using an account.</p></div><button class="quiet" id="refresh-quotas">Refresh</button></div><div class="table-wrap"><table><thead><tr><th>Account</th><th>Provider</th><th>Concurrency</th><th>Cooldown</th><th>Status</th></tr></thead><tbody id="quota-accounts"></tbody></table></div></article>
<article class="panel"><div class="panel-head"><div><h2>Immutable policy windows</h2><p>Every active window is enforced simultaneously.</p></div></div><div class="table-wrap"><table><thead><tr><th>Account</th><th>Window</th><th>Requests</th><th>Pages</th><th>Estimated</th><th>Billed exposure</th></tr></thead><tbody id="quota-policies"></tbody></table></div></article>
<article class="panel"><div class="panel-head"><div><h2>Usage ledger</h2><p>Reserved, committed, ambiguous, and released attempts remain visible.</p></div></div><div class="table-wrap"><table><thead><tr><th>Account</th><th>State</th><th>Attempts</th><th>Requests</th><th>Pages</th><th>Estimate</th><th>Billed</th><th>Credits</th></tr></thead><tbody id="quota-usage"></tbody></table></div></article>
<article class="panel"><div class="panel-head"><div><h2>Reconciliation queue</h2><p>Resolve only after checking the provider dashboard or durable checkpoint.</p></div></div><div class="table-wrap"><table><thead><tr><th>Job</th><th>Account</th><th>State</th><th>Reserved</th><th>Deadline</th><th></th></tr></thead><tbody id="quota-ambiguous"></tbody></table></div></article>
<article class="panel"><div class="panel-head"><div><h2>Unused overage allowances</h2><p>Allowances are exact-recipe, expiring, and single-use.</p></div></div><div class="table-wrap"><table><thead><tr><th>Job</th><th>Reason</th><th>Allowance</th><th>Expires</th><th></th></tr></thead><tbody id="quota-overrides"></tbody></table></div></article></section>

<section class="view" id="view-access"><div class="section-actions"><p>Revocable administrator tokens provide API access without sharing the deployment bootstrap secret.</p><button class="primary" id="open-token">Create admin token</button></div>
<div class="panel table-wrap"><table><thead><tr><th>Label</th><th>Prefix</th><th>Created</th><th>Last used</th><th>Status</th><th></th></tr></thead><tbody id="tokens-body"></tbody></table></div></section>
</main></div>

<dialog id="upload-dialog"><form method="dialog" class="dialog-card" id="upload-form"><div class="dialog-head"><div><p class="eyebrow">New job</p><h2>Add a source</h2></div><button class="icon" value="cancel" aria-label="Close">×</button></div>
<label>File<input required id="upload-file" type="file"></label><div class="form-grid"><label>Priority<select id="upload-priority"><option>1_urgent</option><option>2_high</option><option selected>3_normal</option><option>4_low</option></select></label>
<label>Media type<input id="upload-media" placeholder="application/pdf"></label></div><label>Tags<input id="upload-tags" placeholder="rulebook, evaluation"></label>
<p class="hint">The file is streamed to BlobForge, hashed on the server, and queued only after the complete upload is durable.</p><progress id="upload-progress" max="100" value="0" hidden></progress>
<div class="dialog-actions"><button value="cancel" class="quiet">Cancel</button><button type="submit" class="primary">Upload and queue</button></div></form></dialog>

<dialog id="worker-dialog"><form method="dialog" class="dialog-card" id="worker-form"><div class="dialog-head"><div><p class="eyebrow">Capacity</p><h2>Register worker</h2></div><button class="icon" value="cancel">×</button></div>
<label>Worker ID<input required id="worker-id" pattern="[a-z0-9][a-z0-9-]{1,62}" placeholder="cpu-workstation"></label><p class="hint">Use a stable, lowercase machine-oriented name. The enrollment token is shown once.</p>
<div class="dialog-actions"><button value="cancel" class="quiet">Cancel</button><button type="submit" class="primary">Create credential</button></div></form></dialog>

<dialog id="token-dialog"><form method="dialog" class="dialog-card" id="token-form"><div class="dialog-head"><div><p class="eyebrow">API access</p><h2>Create admin token</h2></div><button class="icon" value="cancel">×</button></div>
<label>Label<input required id="token-label" maxlength="120" placeholder="workstation CLI"></label><label>Expires in days <input id="token-days" type="number" min="1" max="3650" placeholder="Never"></label>
<div class="dialog-actions"><button value="cancel" class="quiet">Cancel</button><button type="submit" class="primary">Create token</button></div></form></dialog>

<dialog id="secret-dialog"><div class="dialog-card"><div class="dialog-head"><div><p class="eyebrow">Shown once</p><h2 id="secret-title">Credential created</h2></div><button class="icon" data-close="secret-dialog">×</button></div>
<p>Copy this credential now. BlobForge stores only its hash and cannot show it again.</p><div class="secret"><code id="secret-value"></code><button class="quiet" id="copy-secret">Copy</button></div><div class="dialog-actions"><button class="primary" data-close="secret-dialog">Done</button></div></div></dialog>

<dialog id="detail-dialog"><div class="dialog-card wide"><div class="dialog-head"><div><p class="eyebrow">Job details</p><h2 id="detail-title"></h2></div><button class="icon" data-close="detail-dialog">×</button></div><div id="detail-content"></div></div></dialog>
<dialog id="recipe-dialog"><form method="dialog" class="dialog-card" id="recipe-form"><div class="dialog-head"><div><p class="eyebrow">Recipe metadata</p><h2>Edit recipe</h2></div><button class="icon" value="cancel">×</button></div>
<input type="hidden" id="recipe-digest"><label>Display name<input id="recipe-name" maxlength="160"></label><label>Notes<textarea id="recipe-notes" rows="5" maxlength="4000"></textarea></label><label class="check"><input id="recipe-enabled" type="checkbox"> Enabled for backend selection</label>
<div class="dialog-actions"><button value="cancel" class="quiet">Cancel</button><button type="submit" class="primary">Save</button></div></form></dialog>
<dialog id="reprocess-dialog"><form method="dialog" class="dialog-card wide" id="reprocess-form"><div class="dialog-head"><div><p class="eyebrow">Immutable derivatives</p><h2>Plan artifact upgrades</h2></div><button class="icon" value="cancel">×</button></div>
<p class="hint">BlobForge will use existing MDAFs as input. Previewing and queueing never reruns the PDF extraction or calls a hosted provider.</p>
<label>Source recipe digest<input required id="reprocess-source" placeholder="blake3:…"></label><label>Target lifecycle recipe<select required id="reprocess-target"><option value="">Select target recipe…</option></select></label>
<label>Queued priority<select id="reprocess-priority"><option>1_urgent</option><option>2_high</option><option selected>3_normal</option><option>4_low</option></select></label>
<pre id="reprocess-result">Preview has not run.</pre><div class="dialog-actions"><button value="cancel" class="quiet">Close</button><button type="submit">Preview</button><button type="button" class="primary" id="execute-reprocess" disabled>Queue eligible</button></div></form></dialog>
<dialog id="provider-account-dialog"><form method="dialog" class="dialog-card" id="provider-account-form"><div class="dialog-head"><div><p class="eyebrow">Hosted capacity</p><h2>Configure provider account</h2></div><button class="icon" value="cancel">×</button></div><label>Logical account key<input required id="provider-account-key" placeholder="mistral:primary"></label><label>Provider<input required id="provider-name" placeholder="mistral-ai"></label><label>Concurrency limit<input required id="provider-concurrency" type="number" min="1" value="1"></label><label class="check"><input id="provider-enabled" type="checkbox" checked> Enabled</label><div class="dialog-actions"><button value="cancel" class="quiet">Cancel</button><button type="submit" class="primary">Save account</button></div></form></dialog>
<dialog id="quota-policy-dialog"><form method="dialog" class="dialog-card wide" id="quota-policy-form"><div class="dialog-head"><div><p class="eyebrow">Immutable budget</p><h2>Add quota policy window</h2></div><button class="icon" value="cancel">×</button></div><label>Provider account<select required id="quota-policy-account"></select></label><label>Label<input id="quota-policy-label" maxlength="160" placeholder="September promotional allowance"></label><div class="form-grid"><label>Starts<input required id="quota-window-start" type="datetime-local"></label><label>Ends<input required id="quota-window-end" type="datetime-local"></label></div><div class="form-grid"><label>Maximum requests<input id="quota-limit-requests" type="number" min="0"></label><label>Maximum pages<input id="quota-limit-pages" type="number" min="0"></label></div><div class="form-grid"><label>Estimated list-price ceiling (USD)<input id="quota-limit-estimated" type="number" min="0" step="0.000001"></label><label>Billed-cash ceiling (USD)<input id="quota-limit-billed" type="number" min="0" step="0.000001"></label></div><p class="hint">Leave unused dimensions empty. Policies cannot be edited after creation.</p><div class="dialog-actions"><button value="cancel" class="quiet">Cancel</button><button type="submit" class="primary">Create policy</button></div></form></dialog>
<dialog id="quota-override-dialog"><form method="dialog" class="dialog-card" id="quota-override-form"><div class="dialog-head"><div><p class="eyebrow">Exceptional purchase</p><h2>Allow one quota overage</h2></div><button class="icon" value="cancel">×</button></div><input type="hidden" id="quota-override-key"><input type="hidden" id="quota-override-recipe"><label>Reason<textarea required id="quota-override-reason" rows="4" maxlength="1000"></textarea></label><div class="form-grid"><label>Extra requests<input id="quota-extra-requests" type="number" min="0" value="1"></label><label>Extra pages<input id="quota-extra-pages" type="number" min="0" value="0"></label></div><label>Extra cost allowance (USD)<input id="quota-extra-cost" type="number" min="0" step="0.000001" value="0"></label><label>Expires in hours<input required id="quota-override-hours" type="number" min="1" max="720" value="24"></label><p class="hint">Single-use. This cannot bypass rights, privacy, recipe limits, cooldowns, or provider-side quota.</p><div class="dialog-actions"><button value="cancel" class="quiet">Cancel</button><button type="submit" class="primary">Create allowance</button></div></form></dialog>
<div id="toast" role="status" aria-live="polite"></div><script src="/static/management-{ASSET_VERSION}.js" defer></script></body></html>"""


CSS = r"""
:root{color-scheme:dark;--bg:#0d1115;--panel:#151b21;--panel2:#1b232b;--line:#2b3640;--text:#edf2f5;--muted:#9ca9b4;--accent:#83e1bc;--danger:#ff7d7d;--warn:#f4c66f;font:15px/1.45 Inter,ui-sans-serif,system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text)}button,input,select,textarea{font:inherit}.shell{min-height:100vh;display:grid;grid-template-columns:15rem 1fr}aside{position:sticky;top:0;height:100vh;padding:1.4rem;display:flex;flex-direction:column;border-right:1px solid var(--line);background:#10161b}.brand{display:flex;align-items:center;gap:.7rem;color:var(--text);font-weight:800;font-size:1.15rem;text-decoration:none}.brand-mark{display:grid;place-items:center;width:2rem;height:2rem;border-radius:.6rem;background:var(--accent);color:#0c1712}nav{display:grid;gap:.35rem;margin-top:2.5rem}.nav,.aside-foot button,.aside-foot a{border:0;background:transparent;color:var(--muted);text-align:left;padding:.7rem .8rem;border-radius:.55rem;text-decoration:none;cursor:pointer}.nav:hover,.nav.active,.aside-foot a:hover,.aside-foot button:hover{background:var(--panel2);color:var(--text)}.aside-foot{margin-top:auto;display:grid}.aside-foot form{margin:0}.aside-foot button{width:100%}main{min-width:0;padding:2rem clamp(1.2rem,4vw,4rem) 4rem}header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:2rem}h1{font-size:clamp(2rem,4vw,3.4rem);line-height:1;margin:.05em 0;letter-spacing:-.045em}h2{margin:.1rem 0;font-size:1.25rem}.eyebrow{margin:0;color:var(--accent);text-transform:uppercase;letter-spacing:.14em;font-size:.72rem;font-weight:800}.identity{text-align:right}.identity span,.identity small{display:block}.identity small,.panel p,.section-actions p,.hint{color:var(--muted)}.view{display:none}.view.active{display:block}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(10rem,1fr));gap:1rem;margin-bottom:1rem}.card,.panel{background:var(--panel);border:1px solid var(--line);border-radius:.9rem}.card{padding:1.2rem}.card strong{display:block;font-size:2rem}.card span{color:var(--muted);text-transform:capitalize}.grid.two{display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1rem}.panel{padding:1.2rem}.panel-head,.section-actions,.toolbar,.pagination,.dialog-head,.dialog-actions{display:flex;align-items:center;justify-content:space-between;gap:1rem}.panel-head{margin-bottom:1rem}.panel-head p,.section-actions p{margin:.2rem 0}.bars{display:grid;gap:.8rem}.bar-row{display:grid;grid-template-columns:7rem 1fr 3rem;align-items:center;gap:.8rem}.bar{height:.5rem;background:#27323b;border-radius:9rem;overflow:hidden}.bar i{display:block;height:100%;background:var(--accent)}.activity{display:grid}.activity-row{display:grid;grid-template-columns:minmax(9rem,1fr) 1.5fr auto;gap:1rem;padding:.7rem 0;border-top:1px solid var(--line)}.toolbar{margin-bottom:1rem;flex-wrap:wrap}.toolbar input{flex:1;min-width:16rem}.section-actions{margin-bottom:1rem}button,.quiet,.primary{border:1px solid var(--line);border-radius:.55rem;padding:.58rem .8rem;background:var(--panel2);color:var(--text);cursor:pointer}button:hover{border-color:#536371}.primary{background:var(--accent);border-color:var(--accent);color:#092016;font-weight:800}.danger{color:#ffb0b0;border-color:#713e43}.quiet{background:transparent}.icon{font-size:1.5rem;border:0;background:transparent;padding:.2rem}.table-wrap{overflow:auto;padding:0}table{width:100%;border-collapse:collapse;min-width:48rem}th,td{padding:.82rem 1rem;text-align:left;border-bottom:1px solid var(--line);vertical-align:middle}th{color:var(--muted);font-size:.75rem;text-transform:uppercase;letter-spacing:.08em}td small{display:block;color:var(--muted)}td.actions{white-space:nowrap;text-align:right}.badge{display:inline-flex;padding:.2rem .48rem;border-radius:9rem;background:#28343d;color:#c7d3da;font-size:.78rem}.badge.done{background:#17392e;color:#9ce8c9}.badge.failed,.badge.dead{background:#47272a;color:#ffb0b0}.badge.processing{background:#44391f;color:#f5d68d}.pagination{padding:1rem}.pagination div{display:flex;gap:.5rem}input,select,textarea{width:100%;border:1px solid var(--line);border-radius:.55rem;background:#0f151a;color:var(--text);padding:.62rem .72rem}textarea{resize:vertical}.toolbar select{width:auto}.toolbar input,.toolbar select{background:var(--panel)}dialog{width:min(94vw,38rem);border:1px solid var(--line);border-radius:1rem;background:transparent;color:var(--text);padding:0}dialog::backdrop{background:#05080bc9;backdrop-filter:blur(4px)}.dialog-card{background:var(--panel);padding:1.4rem;display:grid;gap:1rem}.dialog-card.wide{width:min(94vw,58rem)}dialog:has(.wide){width:min(94vw,58rem)}label{display:grid;gap:.4rem;color:#cad3da}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.dialog-actions{justify-content:flex-end}.check{display:flex;align-items:center}.check input{width:auto}.secret{display:flex;gap:.5rem;align-items:center;background:#0b1014;border:1px solid var(--line);padding:.8rem;border-radius:.6rem;overflow:auto}.secret code{flex:1;color:var(--accent);word-break:break-all}.key-value{display:grid;grid-template-columns:10rem 1fr;gap:.4rem 1rem;margin:1rem 0}.key-value dt{color:var(--muted)}.key-value dd{margin:0;overflow-wrap:anywhere}.detail-actions{display:flex;flex-wrap:wrap;gap:.5rem;margin:1rem 0}.artifact,.failure{padding:.8rem 0;border-top:1px solid var(--line)}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#0d1216;padding:.8rem;border-radius:.55rem;color:#bdc8d0}#toast{position:fixed;right:1.2rem;bottom:1.2rem;max-width:28rem;background:#23302c;border:1px solid #426b5b;padding:.8rem 1rem;border-radius:.6rem;opacity:0;transform:translateY(1rem);pointer-events:none;transition:.2s}#toast.show{opacity:1;transform:none}progress{width:100%}@media(max-width:760px){.shell{display:block}aside{position:static;height:auto;border-right:0;border-bottom:1px solid var(--line)}aside nav{display:flex;overflow:auto;margin-top:1rem}.aside-foot{display:none}main{padding:1.2rem}.grid.two{grid-template-columns:1fr}header{align-items:end}.identity{max-width:45%;overflow:hidden}.form-grid{grid-template-columns:1fr}.activity-row{grid-template-columns:1fr}.toolbar>*{width:100%!important}}
"""


JS = r"""
const state={view:'dashboard',offset:0,limit:50,total:0,recipes:[],jobs:[]};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const when=v=>v?new Date(Number(v)).toLocaleString():'—';
const bytes=v=>{let n=Number(v||0),u=['B','KiB','MiB','GiB'];let i=0;while(n>=1024&&i<u.length-1){n/=1024;i++}return `${n.toFixed(i?1:0)} ${u[i]}`};
const usd=v=>v===null||v===undefined?'—':`$${(Number(v)/1000000).toFixed(4)}`;
let toastTimer; function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}
async function api(path,options={}){const opts={credentials:'same-origin',...options};opts.headers={'Accept':'application/json',...(opts.body?{'Content-Type':'application/json'}:{}),...(opts.headers||{})};const response=await fetch(path,opts);let body=null;try{body=await response.json()}catch{}if(!response.ok)throw new Error(body?.detail||body?.error||`Request failed (${response.status})`);return body}
function uploadFile(path,file,progress){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST',path);xhr.setRequestHeader('Accept','application/json');xhr.upload.onprogress=e=>{if(e.lengthComputable)progress.value=Math.round(e.loaded/e.total*100)};xhr.onload=()=>{let body={};try{body=JSON.parse(xhr.responseText)}catch{}if(xhr.status>=200&&xhr.status<300)resolve(body);else reject(new Error(body.detail||body.error||`Upload failed (${xhr.status})`))};xhr.onerror=()=>reject(new Error('Upload connection failed'));xhr.send(file)})}
function show(view){state.view=view;$$('.view').forEach(x=>x.classList.toggle('active',x.id===`view-${view}`));$$('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===view));const names={dashboard:['Administration','Overview'],jobs:['Work queue','Jobs'],workers:['Conversion fleet','Workers'],recipes:['Output identities','Recipes'],quotas:['Hosted providers','Quotas'],access:['Credentials','Access']};$('#view-kicker').textContent=names[view][0];$('#view-title').textContent=names[view][1];if(view==='dashboard')loadOverview();if(view==='jobs')loadJobs();if(view==='workers')loadWorkers();if(view==='recipes')loadRecipes();if(view==='quotas'){loadQuotas();loadQuotaActions()}if(view==='access')loadTokens()}
$$('.nav').forEach(x=>x.addEventListener('click',()=>show(x.dataset.view)));$$('[data-go]').forEach(x=>x.addEventListener('click',()=>show(x.dataset.go)));$$('[data-close]').forEach(x=>x.addEventListener('click',()=>document.getElementById(x.dataset.close).close()));
async function loadOverview(){try{const data=await api('/api/v1/admin/overview');const order=['todo','processing','failed','dead','done'];$('#overview-cards').innerHTML=order.map(k=>`<div class="card"><strong>${Number(data.counts[k]||0).toLocaleString()}</strong><span>${esc(k)}</span></div>`).join('');const max=Math.max(1,...Object.values(data.priority||{}));$('#priority-chart').innerHTML=Object.entries(data.priority||{}).map(([k,v])=>`<div class="bar-row"><span>${esc(k)}</span><progress max="${max}" value="${v}"></progress><strong>${v}</strong></div>`).join('')||'<p class="hint">The queue is empty.</p>';$('#worker-summary').innerHTML=`<div class="cards"><div class="card"><strong>${data.workers.online}</strong><span>online</span></div><div class="card"><strong>${data.workers.total}</strong><span>registered</span></div></div>`;$('#audit-list').innerHTML=(data.audit||[]).map(x=>`<div class="activity-row"><strong>${esc(x.action)}</strong><span>${esc(x.target)}</span><small>${when(x.created_at)}</small></div>`).join('')||'<p class="hint">No administrative changes recorded yet.</p>'}catch(e){toast(e.message)}}
$('#refresh-overview').addEventListener('click',loadOverview);
function jobParams(){const p=new URLSearchParams({limit:state.limit,offset:state.offset});[['search','#job-search'],['status','#job-status'],['priority','#job-priority']].forEach(([k,s])=>{if($(s).value)p.set(k,$(s).value)});return p}
function jobRow(j){const error=j.error_message?'<small>'+esc(j.error_message)+'</small>':'';const options=['1_urgent','2_high','3_normal','4_low'].map(p=>'<option '+(p===j.priority?'selected':'')+'>'+p+'</option>').join('');return `<tr><td><strong>${esc(j.original_name||'Unnamed source')}</strong><small>${esc(j.hash.slice(0,16))}… · ${bytes(j.size_bytes)} · ${esc(j.media_type)}</small></td><td><span class="badge ${esc(j.status)}">${esc(j.status)}</span>${error}</td><td><select class="priority-select" data-key="${esc(j.hash)}">${options}</select></td><td><small>${j.recipe_digest?esc(j.recipe_digest.slice(0,12))+'…':'automatic'}</small></td><td>${when(j.updated_at)}</td><td class="actions"><button class="quiet job-detail" data-key="${esc(j.hash)}">Manage</button></td></tr>`}
async function loadJobs(){try{const data=await api(`/api/v1/admin/jobs?${jobParams()}`);state.jobs=data.jobs;state.total=data.total;$('#jobs-total').textContent=`${data.total.toLocaleString()} jobs`;$('#jobs-prev').disabled=state.offset===0;$('#jobs-next').disabled=state.offset+state.limit>=data.total;$('#jobs-body').innerHTML=data.jobs.map(jobRow).join('')||'<tr><td colspan="6">No jobs match these filters.</td></tr>';$$('.priority-select').forEach(x=>x.addEventListener('change',()=>setPriority(x.dataset.key,x.value)));$$('.job-detail').forEach(x=>x.addEventListener('click',()=>openJob(x.dataset.key)))}catch(e){toast(e.message)}}
let searchTimer;$('#job-search').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{state.offset=0;loadJobs()},250)});['#job-status','#job-priority'].forEach(s=>$(s).addEventListener('change',()=>{state.offset=0;loadJobs()}));$('#jobs-prev').addEventListener('click',()=>{state.offset=Math.max(0,state.offset-state.limit);loadJobs()});$('#jobs-next').addEventListener('click',()=>{state.offset+=state.limit;loadJobs()});
async function setPriority(key,priority){try{await api(`/api/v1/admin/jobs/${key}/priority`,{method:'PATCH',body:JSON.stringify({priority})});toast('Priority updated')}catch(e){toast(e.message);loadJobs()}}
async function openJob(key){try{const d=await api(`/api/v1/admin/jobs/${key}`),j=d.job;$('#detail-title').textContent=j.original_name||j.hash;const recipes=state.recipes.length?state.recipes:(await api('/api/v1/recipes')).recipes;state.recipes=recipes;const retryLabel=j.status==='processing'?'Stop and requeue':(['failed','dead'].includes(j.status)?'Retry':'Requeue');const requeue=j.status!=='done'?'<button class="job-requeue" data-key="'+esc(j.hash)+'">'+retryLabel+'</button>':'';const reset=j.status==='dead'?'<button class="job-reset" data-key="'+esc(j.hash)+'">Reset attempts and retry</button>':'';const recipeOptions=recipes.filter(r=>r.enabled).map(r=>'<option value="'+esc(r.recipe_digest)+'">'+esc(r.display_name||r.backend)+' · '+esc(r.recipe_digest.slice(0,10))+'</option>').join('');const selectedRecipe=recipes.find(r=>r.recipe_digest===j.recipe_digest),quotaButton=selectedRecipe?.provider_account?'<button class="job-quota">Allow one quota overage</button>':'';const canUpgrade=recipes.some(r=>r.enabled&&(r.input_kinds||[]).includes('artifact'));const artifacts=d.artifacts.map(a=>'<div class="artifact"><strong>'+esc(a.artifact_type)+'</strong><small>'+esc(a.recipe_digest)+' · '+bytes(a.size_bytes)+(a.legacy?' · legacy':'')+'</small><button class="quiet artifact-download" data-recipe="'+esc(a.recipe_digest)+'">Download</button>'+(canUpgrade?'<button class="quiet artifact-upgrade" data-recipe="'+esc(a.recipe_digest)+'">Plan upgrade</button>':'')+'</div>').join('')||'<p class="hint">No artifacts.</p>';const failures=d.failures.map(f=>'<div class="failure"><strong>Attempt '+f.attempt+' · '+when(f.created_at)+'</strong><p>'+esc(f.error)+'</p>'+(f.traceback?'<pre>'+esc(f.traceback)+'</pre>':'')+'</div>').join('')||'<p class="hint">No failures.</p>';const quota=(d.quota?.reservations||[]).map(q=>'<div class="failure"><strong>'+esc(q.state)+' · '+when(q.created_at)+'</strong><p>'+esc(q.account_key)+' · '+q.reserved_pages+' pages · '+usd(q.reserved_estimated_micro_usd)+(q.override_id?' · override '+esc(q.override_id):'')+'</p></div>').join('')||'<p class="hint">No hosted-provider attempts.</p>';$('#detail-content').innerHTML=`<dl class="key-value"><dt>Source key</dt><dd><code>${esc(j.hash)}</code></dd><dt>State</dt><dd><span class="badge ${esc(j.status)}">${esc(j.status)}</span></dd><dt>Priority</dt><dd>${esc(j.priority)}</dd><dt>Media</dt><dd>${esc(j.media_type)}</dd><dt>Input</dt><dd>${esc(j.input_kind||'source')}${j.parent_recipe_digest?' · '+esc(j.parent_recipe_digest):''}</dd><dt>Tags</dt><dd>${esc((j.tags||[]).join(', ')||'—')}</dd><dt>Paths</dt><dd>${esc((j.paths||[]).join(', ')||'—')}</dd><dt>Retries</dt><dd>${j.retry_count}</dd><dt>Worker</dt><dd>${esc(j.worker_id||'—')}</dd><dt>Deferred until</dt><dd>${when(j.not_before)}</dd><dt>Blocked reason</dt><dd>${esc(j.blocked_reason||'—')}</dd></dl><div class="detail-actions"><button class="job-source">Download source</button>${requeue}${reset}${quotaButton}<select id="detail-recipe"><option value="">Select conversion recipe…</option>${recipeOptions}</select><button class="job-convert" data-key="${esc(j.hash)}">Request conversion</button><button class="danger job-delete" data-key="${esc(j.hash)}">Delete source</button></div><h3>Artifacts</h3>${artifacts}<h3>Provider quota history</h3>${quota}<h3>Failure history</h3>${failures}`;$('.job-source').addEventListener('click',()=>downloadSource(key));$$('.artifact-download').forEach(x=>x.addEventListener('click',()=>downloadArtifact(key,x.dataset.recipe)));$$('.artifact-upgrade').forEach(x=>x.addEventListener('click',()=>{openReprocess(x.dataset.recipe,[key]);$('#detail-dialog').close()}));$('.job-requeue')?.addEventListener('click',()=>requeueJob(key,false));$('.job-reset')?.addEventListener('click',()=>requeueJob(key,true));$('.job-quota')?.addEventListener('click',()=>{openQuotaOverride(key,j.recipe_digest);$('#detail-dialog').close()});$('.job-convert').addEventListener('click',()=>convertJob(key));$('.job-delete').addEventListener('click',()=>deleteJob(key));$('#detail-dialog').showModal()}catch(e){toast(e.message)}}
async function downloadSource(key){try{const value=await api(`/api/v1/admin/jobs/${key}/source-url`);location.assign(value.url)}catch(e){toast(e.message)}}async function downloadArtifact(key,recipe){try{const value=await api(`/api/v1/jobs/${key}/download-url`,{method:'POST',body:JSON.stringify({recipe_digest:recipe})});location.assign(value.url)}catch(e){toast(e.message)}}
async function requeueJob(key,reset){if(!confirm(reset?'Reset the retry counter and return this job to the queue?':'Release any active lease and return this job to the queue?'))return;try{await api(`/api/v1/admin/jobs/${key}/retry`,{method:'POST',body:JSON.stringify({reset_retries:reset})});$('#detail-dialog').close();toast(reset?'Retry counter reset and job queued':'Job requeued');loadJobs()}catch(e){toast(e.message)}}
async function convertJob(key){const digest=$('#detail-recipe').value;if(!digest){toast('Select a recipe first');return}try{await api(`/api/v1/jobs/${key}/convert`,{method:'POST',body:JSON.stringify({recipe_digest:digest})});$('#detail-dialog').close();toast('Conversion requested');loadJobs()}catch(e){toast(e.message)}}
async function deleteJob(key){if(!confirm('Delete this job and move its source and artifacts to recoverable server trash?'))return;try{await api(`/api/v1/admin/jobs/${key}`,{method:'DELETE'});$('#detail-dialog').close();toast('Job deleted; files moved to trash');loadJobs()}catch(e){toast(e.message)}}
$('#open-upload').addEventListener('click',()=>$('#upload-dialog').showModal());$('#upload-file').addEventListener('change',e=>{const f=e.target.files[0];if(f&&!$('#upload-media').value)$('#upload-media').value=f.type||'application/octet-stream'});
$('#upload-form').addEventListener('submit',async e=>{e.preventDefault();const file=$('#upload-file').files[0];if(!file)return;const progress=$('#upload-progress');progress.hidden=false;progress.value=0;try{const params=new URLSearchParams({filename:file.name,media_type:$('#upload-media').value||file.type||'application/octet-stream',priority:$('#upload-priority').value,tags:$('#upload-tags').value});await uploadFile(`/api/v1/admin/uploads?${params}`,file,progress);progress.value=100;$('#upload-dialog').close();e.target.reset();toast('Source uploaded and queued');state.offset=0;loadJobs()}catch(err){toast(err.message)}finally{setTimeout(()=>{progress.hidden=true;progress.value=0},700)}});
function workerRow(w){const managed=w.managed_by==='environment';const revoke=!w.revoked&&!managed?'<button class="danger worker-revoke" data-id="'+esc(w.worker_id)+'">Revoke</button>':'';const rotate=!managed?'<button class="quiet worker-rotate" data-id="'+esc(w.worker_id)+'">Rotate</button>':'<small>Change in deployment config</small>';return `<tr><td><strong>${esc(w.worker_id)}</strong><small>${w.current_job?'Job '+esc(w.current_job.slice(0,12))+'…':''}</small></td><td><span class="badge ${esc(w.status)}">${w.revoked?'revoked':esc(w.status)}</span></td><td>${esc(w.hostname||'—')}</td><td>${when(w.last_seen)}</td><td>${esc(w.managed_by)}</td><td class="actions">${rotate} ${revoke}</td></tr>`}
async function loadWorkers(){try{const data=await api('/api/v1/admin/workers');$('#workers-body').innerHTML=data.workers.map(workerRow).join('')||'<tr><td colspan="6">No workers registered.</td></tr>';$$('.worker-rotate').forEach(x=>x.addEventListener('click',()=>rotateWorker(x.dataset.id)));$$('.worker-revoke').forEach(x=>x.addEventListener('click',()=>revokeWorker(x.dataset.id)))}catch(e){toast(e.message)}}
$('#open-worker').addEventListener('click',()=>$('#worker-dialog').showModal());$('#worker-form').addEventListener('submit',async e=>{e.preventDefault();try{const value=await api('/api/v1/admin/workers',{method:'POST',body:JSON.stringify({worker_id:$('#worker-id').value})});$('#worker-dialog').close();e.target.reset();showSecret('Worker credential',value.token);loadWorkers()}catch(err){toast(err.message)}});
async function rotateWorker(id){if(!confirm(`Rotate the credential for ${id}? The previous token will stop working immediately.`))return;try{const value=await api(`/api/v1/admin/workers/${encodeURIComponent(id)}/token`,{method:'POST',body:'{}'});showSecret('Replacement worker credential',value.token);loadWorkers()}catch(e){toast(e.message)}}async function revokeWorker(id){if(!confirm(`Revoke ${id}? It will no longer be able to claim or finish jobs.`))return;try{await api(`/api/v1/admin/workers/${encodeURIComponent(id)}/revoke`,{method:'POST',body:'{}'});toast('Worker revoked');loadWorkers()}catch(e){toast(e.message)}}
async function loadRecipes(){try{const data=await api('/api/v1/recipes');state.recipes=data.recipes;$('#recipes-body').innerHTML=data.recipes.map(r=>`<tr><td><strong>${esc(r.display_name||r.backend)}</strong><small><code>${esc(r.recipe_digest)}</code></small></td><td>${esc(r.backend)}</td><td>${esc(r.media_types.join(', '))}</td><td>${r.worker_count}</td><td><span class="badge ${r.enabled?'done':'dead'}">${r.enabled?'enabled':'retired'}</span></td><td class="actions"><button class="quiet recipe-edit" data-digest="${esc(r.recipe_digest)}">Edit</button></td></tr>`).join('')||'<tr><td colspan="6">Recipes appear when a worker advertises a capability.</td></tr>';$$('.recipe-edit').forEach(x=>x.addEventListener('click',()=>editRecipe(x.dataset.digest)))}catch(e){toast(e.message)}}
function editRecipe(digest){const r=state.recipes.find(x=>x.recipe_digest===digest);if(!r)return;$('#recipe-digest').value=digest;$('#recipe-name').value=r.display_name||'';$('#recipe-notes').value=r.notes||'';$('#recipe-enabled').checked=r.enabled;$('#recipe-dialog').showModal()}$('#recipe-form').addEventListener('submit',async e=>{e.preventDefault();const digest=$('#recipe-digest').value;try{await api(`/api/v1/admin/recipes/${encodeURIComponent(digest)}`,{method:'PATCH',body:JSON.stringify({display_name:$('#recipe-name').value,notes:$('#recipe-notes').value,enabled:$('#recipe-enabled').checked})});$('#recipe-dialog').close();toast('Recipe metadata updated');loadRecipes()}catch(err){toast(err.message)}});
let reprocessPlan=null,reprocessKeys=null;async function openReprocess(sourceRecipe='',keys=null){if(!state.recipes.length)await loadRecipes();reprocessKeys=keys;$('#reprocess-source').value=sourceRecipe;$('#reprocess-target').innerHTML='<option value="">Select target recipe…</option>'+state.recipes.filter(r=>r.enabled&&(r.input_kinds||[]).includes('artifact')).map(r=>`<option value="${esc(r.recipe_digest)}">${esc(r.display_name||r.backend)} · ${esc(r.recipe_digest.slice(0,16))}…</option>`).join('');$('#reprocess-result').textContent=keys?`Preview has not run. Limited to ${keys.length} selected source.`:'Preview has not run.';$('#execute-reprocess').disabled=true;reprocessPlan=null;$('#reprocess-dialog').showModal()}$('#open-reprocess').addEventListener('click',()=>openReprocess());
function reprocessBody(execute){const body={source_recipe_digest:$('#reprocess-source').value.trim(),target_recipe_digest:$('#reprocess-target').value,priority:$('#reprocess-priority').value,execute};if(reprocessKeys)body.source_keys=reprocessKeys;return body}
$('#reprocess-form').addEventListener('submit',async e=>{e.preventDefault();try{reprocessPlan=await api('/api/v1/admin/reprocessing',{method:'POST',body:JSON.stringify(reprocessBody(false))});$('#reprocess-result').textContent=JSON.stringify(reprocessPlan,null,2);$('#execute-reprocess').disabled=!reprocessPlan.eligible;toast(`Found ${reprocessPlan.eligible} eligible artifact${reprocessPlan.eligible===1?'':'s'}`)}catch(err){reprocessPlan=null;$('#execute-reprocess').disabled=true;toast(err.message)}});
$('#execute-reprocess').addEventListener('click',async()=>{if(!reprocessPlan?.eligible||!confirm(`Queue ${reprocessPlan.eligible} immutable artifact upgrade${reprocessPlan.eligible===1?'':'s'}?`))return;try{const result=await api('/api/v1/admin/reprocessing',{method:'POST',body:JSON.stringify(reprocessBody(true))});$('#reprocess-result').textContent=JSON.stringify(result,null,2);$('#execute-reprocess').disabled=true;toast(`Queued ${result.queued} artifact upgrade${result.queued===1?'':'s'}`)}catch(err){toast(err.message)}});
let quotaData={accounts:[],policies:[],usage:[]};
async function loadQuotas(){try{quotaData=await api('/api/v1/admin/quotas');$('#quota-cards').innerHTML=`<div class="card"><strong>${quotaData.accounts.length}</strong><span>provider accounts</span></div><div class="card"><strong>${quotaData.waiting_jobs}</strong><span>waiting jobs</span></div><div class="card"><strong>${quotaData.usage.filter(x=>x.state==='ambiguous').reduce((n,x)=>n+Number(x.attempts),0)}</strong><span>ambiguous attempts</span></div>`;$('#quota-accounts').innerHTML=quotaData.accounts.map(a=>`<tr><td><strong>${esc(a.account_key)}</strong></td><td>${esc(a.provider)}</td><td>${a.concurrency_limit}</td><td>${a.cooldown_until?when(a.cooldown_until)+' · '+esc(a.cooldown_reason||''): '—'}</td><td><span class="badge ${a.enabled?'done':'dead'}">${a.enabled?'enabled':'disabled'}</span></td></tr>`).join('')||'<tr><td colspan="5">No provider accounts configured.</td></tr>';$('#quota-policies').innerHTML=quotaData.policies.map(p=>`<tr><td><strong>${esc(p.account_key)}</strong><small>${esc(p.label||`revision ${p.revision}`)} · ${p.active?'active':'inactive'}</small></td><td>${when(p.window_start)}<small>until ${when(p.window_end)}</small></td><td>${p.usage.requests} / ${p.limit_requests??'∞'}</td><td>${p.usage.pages} / ${p.limit_pages??'∞'}</td><td>${usd(p.usage.estimated_micro_usd)} / ${usd(p.limit_estimated_micro_usd)}</td><td>${usd(p.usage.billed_exposure_micro_usd)} / ${usd(p.limit_billed_micro_usd)}</td></tr>`).join('')||'<tr><td colspan="6">No quota windows configured.</td></tr>';$('#quota-usage').innerHTML=quotaData.usage.map(u=>`<tr><td>${esc(u.account_key)}</td><td><span class="badge ${u.state==='committed'?'done':u.state==='ambiguous'?'failed':''}">${esc(u.state)}</span></td><td>${u.attempts}</td><td>${u.requests}</td><td>${u.pages}</td><td>${usd(u.estimated_micro_usd)}</td><td>${usd(u.billed_micro_usd)}</td><td>${usd(u.credits_micro_usd)}</td></tr>`).join('')||'<tr><td colspan="8">No provider attempts recorded.</td></tr>'}catch(e){toast(e.message)}}
async function loadQuotaActions(){try{const data=await api('/api/v1/admin/quotas');$('#quota-ambiguous').innerHTML=(data.ambiguous||[]).map(q=>`<tr><td><code>${esc(q.source_key.slice(0,16))}…</code><small>${esc(q.id)}</small></td><td>${esc(q.account_key)}</td><td><span class="badge failed">${esc(q.state)}</span></td><td>${q.reserved_pages} pages · ${usd(q.reserved_estimated_micro_usd)}</td><td>${when(q.reconcile_by)}</td><td class="actions"><button class="quiet quota-commit" data-id="${esc(q.id)}">Confirm purchase</button><button class="danger quota-release" data-id="${esc(q.id)}">Confirm no purchase</button></td></tr>`).join('')||'<tr><td colspan="6">No reservations need reconciliation.</td></tr>';$('#quota-overrides').innerHTML=(data.overrides||[]).map(o=>`<tr><td><code>${esc(o.source_key.slice(0,16))}…</code><small>${esc(o.recipe_digest)}</small></td><td>${esc(o.reason)}</td><td>${o.extra_requests} requests · ${o.extra_pages} pages · ${usd(o.extra_micro_usd)}</td><td>${when(o.expires_at)}</td><td class="actions"><button class="danger quota-override-revoke" data-id="${esc(o.id)}">Revoke</button></td></tr>`).join('')||'<tr><td colspan="5">No unused allowances.</td></tr>';$$('.quota-commit').forEach(x=>x.addEventListener('click',()=>reconcileQuota(x.dataset.id,'committed')));$$('.quota-release').forEach(x=>x.addEventListener('click',()=>reconcileQuota(x.dataset.id,'released')));$$('.quota-override-revoke').forEach(x=>x.addEventListener('click',()=>revokeQuotaOverride(x.dataset.id)))}catch(e){toast(e.message)}}
async function reconcileQuota(id,state){const detail=prompt(state==='committed'?'Evidence that the provider purchase occurred:':'Evidence that no provider purchase occurred:');if(!detail)return;const body={state,detail};if(state==='committed'){const billed=prompt('Actual billed USD, if known (leave empty if unknown):','');const credits=prompt('Credits/discount USD, if known (leave empty if unknown):','');if(billed!=='')body.billed_micro_usd=Math.round(Number(billed)*1000000);if(credits!=='')body.credits_micro_usd=Math.round(Number(credits)*1000000)}try{await api(`/api/v1/admin/quota-reservations/${id}/reconcile`,{method:'POST',body:JSON.stringify(body)});toast('Reservation reconciled');loadQuotas();loadQuotaActions()}catch(e){toast(e.message)}}
async function revokeQuotaOverride(id){if(!confirm('Revoke this unused quota allowance?'))return;try{await api(`/api/v1/admin/quota-overrides/${id}/revoke`,{method:'POST',body:'{}'});toast('Allowance revoked');loadQuotaActions()}catch(e){toast(e.message)}}
$('#refresh-quotas').addEventListener('click',()=>{loadQuotas();loadQuotaActions()});$('#open-provider-account').addEventListener('click',()=>$('#provider-account-dialog').showModal());$('#provider-account-form').addEventListener('submit',async e=>{e.preventDefault();const key=$('#provider-account-key').value.trim();try{await api(`/api/v1/admin/provider-accounts/${encodeURIComponent(key)}`,{method:'PUT',body:JSON.stringify({provider:$('#provider-name').value.trim(),concurrency_limit:Number($('#provider-concurrency').value),enabled:$('#provider-enabled').checked})});$('#provider-account-dialog').close();e.target.reset();$('#provider-concurrency').value=1;$('#provider-enabled').checked=true;toast('Provider account saved');loadQuotas()}catch(err){toast(err.message)}});
const localDateTime=d=>new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);
$('#open-quota-policy').addEventListener('click',async()=>{if(!quotaData.accounts.length)await loadQuotas();$('#quota-policy-account').innerHTML=quotaData.accounts.filter(a=>a.enabled).map(a=>`<option value="${esc(a.account_key)}">${esc(a.account_key)} · ${esc(a.provider)}</option>`).join('');if(!$('#quota-policy-account').options.length){toast('Configure an enabled provider account first');return}const now=new Date(),end=new Date(now.getTime()+30*86400000);$('#quota-window-start').value=localDateTime(now);$('#quota-window-end').value=localDateTime(end);$('#quota-policy-dialog').showModal()});
const optionalInt=s=>$(s).value===''?null:Number($(s).value);const optionalMicro=s=>$(s).value===''?null:Math.round(Number($(s).value)*1000000);
$('#quota-policy-form').addEventListener('submit',async e=>{e.preventDefault();const body={account_key:$('#quota-policy-account').value,label:$('#quota-policy-label').value,window_start:new Date($('#quota-window-start').value).getTime(),window_end:new Date($('#quota-window-end').value).getTime(),limit_requests:optionalInt('#quota-limit-requests'),limit_pages:optionalInt('#quota-limit-pages'),limit_estimated_micro_usd:optionalMicro('#quota-limit-estimated'),limit_billed_micro_usd:optionalMicro('#quota-limit-billed')};try{await api('/api/v1/admin/quota-policies',{method:'POST',body:JSON.stringify(body)});$('#quota-policy-dialog').close();e.target.reset();toast('Immutable quota policy created');loadQuotas()}catch(err){toast(err.message)}});
function openQuotaOverride(key,recipe){$('#quota-override-key').value=key;$('#quota-override-recipe').value=recipe;$('#quota-override-dialog').showModal()}
$('#quota-override-form').addEventListener('submit',async e=>{e.preventDefault();const key=$('#quota-override-key').value,body={recipe_digest:$('#quota-override-recipe').value,reason:$('#quota-override-reason').value,extra_requests:Number($('#quota-extra-requests').value||0),extra_pages:Number($('#quota-extra-pages').value||0),extra_micro_usd:Math.round(Number($('#quota-extra-cost').value||0)*1000000),expires_at:Date.now()+Number($('#quota-override-hours').value)*3600000};if(!confirm('Create this single-use quota allowance? It will be permanently audited.'))return;body.confirm=true;try{await api(`/api/v1/admin/jobs/${key}/quota-overrides`,{method:'POST',body:JSON.stringify(body)});$('#quota-override-dialog').close();e.target.reset();$('#quota-extra-requests').value=1;$('#quota-extra-pages').value=0;$('#quota-extra-cost').value=0;$('#quota-override-hours').value=24;toast('Quota allowance created; job is eligible again');loadJobs()}catch(err){toast(err.message)}});
function tokenRow(t){const revoke=!t.revoked_at?'<button class="danger token-revoke" data-id="'+esc(t.id)+'">Revoke</button>':'';return `<tr><td><strong>${esc(t.label)}</strong></td><td><code>${esc(t.token_prefix)}…</code></td><td>${when(t.created_at)}</td><td>${when(t.last_used)}</td><td><span class="badge ${t.revoked_at?'dead':'done'}">${t.revoked_at?'revoked':'active'}</span></td><td class="actions">${revoke}</td></tr>`}
async function loadTokens(){try{const data=await api('/api/v1/admin/tokens');$('#tokens-body').innerHTML=data.tokens.map(tokenRow).join('')||'<tr><td colspan="6">No revocable admin tokens.</td></tr>';$$('.token-revoke').forEach(x=>x.addEventListener('click',()=>revokeToken(x.dataset.id)))}catch(e){toast(e.message)}}
$('#open-token').addEventListener('click',()=>$('#token-dialog').showModal());$('#token-form').addEventListener('submit',async e=>{e.preventDefault();const days=Number($('#token-days').value||0);try{const value=await api('/api/v1/admin/tokens',{method:'POST',body:JSON.stringify({label:$('#token-label').value,expires_in_days:days||null})});$('#token-dialog').close();e.target.reset();showSecret('Administrator token',value.token);loadTokens()}catch(err){toast(err.message)}});async function revokeToken(id){if(!confirm('Revoke this administrator token immediately?'))return;try{await api(`/api/v1/admin/tokens/${id}/revoke`,{method:'POST',body:'{}'});toast('Token revoked');loadTokens()}catch(e){toast(e.message)}}
function showSecret(title,value){$('#secret-title').textContent=title;$('#secret-value').textContent=value;$('#secret-dialog').showModal()}$('#copy-secret').addEventListener('click',async()=>{await navigator.clipboard.writeText($('#secret-value').textContent);toast('Copied to clipboard')});
$('#logout-form').addEventListener('submit',async e=>{e.preventDefault();await fetch('/auth/logout',{method:'POST',credentials:'same-origin'});location.assign('/auth/login')});
show('dashboard');
"""
